def curriculum():
    library=strategy_library()
    reference=json.loads((ROOT/'sindhu_web/static/concepts_reference.json').read_text(encoding='utf-8'))
    modules=[]
    for ident,title,definition,rule,confirmation,invalidation,limitation,example,keywords,mode in LESSONS:
        matches=[s['id'] for s in library if any(k in ' '.join(s.get('concepts',[])+s.get('indicators',[])).lower() for k in keywords)]
        modules.append({'id':ident,'title':title,'definition':definition,'detection_rules':rule,
                        'required_data':'Closed, validated, native-timeframe OHLCV; '+('venue derivative/book feed' if ident=='derivatives' else 'explicit risk/context metadata where relevant'),
                        'interpretation':{'bullish':'Apply the upward rule only after confirmation.','bearish':'Apply its downward counterpart.','neutral':'Unconfirmed, conflicting or nondirectional evidence; do not force a trade.'},
                        'confirmation':confirmation,'invalidation':invalidation,'limitations':limitation,
                        'worked_example':example,'strategy_ids':matches,'mode':mode,
                        'test_cases':{'positive':example,'negative':invalidation,'boundary':limitation},
                        'exam_status':'See executable exam coverage; narrative scenarios are not counted as passed tests.'})
    return {'version':'1.0.0','modules':modules,'existing_reference':reference,'strategy_count':len(library),
            'sources':SOURCES,'warning':'Educational research conventions. No trading profit or institutional intent is inferred.'}
